/* Connected MESORA workspace. Existing national atlas remains available. */
window.Workspace=(()=>{
 const R=MesoraRotation,el=s=>document.querySelector(s),html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(n,d=1)=>Number.isFinite(+n)?Number(n).toLocaleString('en-US',{maximumFractionDigits:d}):'Unavailable';
 const link=(u,t)=>`<a href="${html(u)}" target="_blank" rel="noopener">${html(t)} ↗</a>`;
 const state={lat:34.98,lon:-80.55,name:'Union County demonstration area',county:'37179',region:'NC',boundary:null,areaHa:10,weather:null,soil:null,watershed:null,monitoring:null,usgs:null,wq:null,year:2025,results:null,route:'explore',loading:false,version:0,date:'2025-07-15',inputs:{years:3,budget:300,previous:['corn'],allowed:Object.keys(R.crops),excluded:[],cover:true,ph:null,drainage:'unknown',weights:{water:4,soil:3,resilience:2,productivity:1}},sim:{warming:2,rainChange:-20,demandM3:100000,coolingSavings:.2,reclaimed:.2,seasonal:.5,shared:false,farmShare:.01},selectedPlan:null};let map,marker,boundaryLayer,drawing=false,points=[],overlay,activeLayer='none';const snaps={};
 async function data(path){if(!snaps[path]){const r=await fetch('data/v2/'+path+'.json');if(!r.ok)throw Error('Snapshot unavailable');snaps[path]=await r.json();}return snaps[path];}
 let requestController;
 async function api(path){return MesoraData.get(path,{signal:requestController?.signal});}

 function atDemo(){return Math.abs(state.lat-34.98)<.00001&&Math.abs(state.lon+80.55)<.00001;}
 async function loadEvidence(){requestController?.abort();requestController=new AbortController();const v=++state.version;state.loading=true;state.attempted=true;state.errors={};state.pending=new Set(['weather','soil','watershed','monitoring','usgs','wq']);state.results=null;const lat=state.lat,lon=state.lon,q=`lat=${lat}&lon=${lon}`;const refresh=()=>{if(v!==state.version)return;const stat=el('#source-status');if(stat)stat.innerHTML=statusContent();if(el('#farm-summary'))updateFarmSummary();const ready=!!state.weather;document.querySelectorAll('#rotation-form button[type=submit],#scenario-form button[type=submit]').forEach(b=>b.disabled=!ready);const message=el('#weather-ready');if(message)message.textContent=ready?'NASA weather is ready. You can calculate now.':'Loading NASA weather for this location…';};
 await Promise.all([...state.pending].map(async key=>{try{let value;if(atDemo()){const paths={weather:'power-daily-union',soil:'soil-union',watershed:'watershed-union',monitoring:'monitoring-union',usgs:'usgs-union',wq:'water-quality'};value=await data(paths[key]);}else if(key==='wq'){const text=await api('water-sites?'+q);value={stations:parseStations(csv(text)),measurements:[],retrieved:new Date().toISOString().slice(0,10),scope:'Within 25 miles of selected point'};}else value=await api(({weather:'power',soil:'soil',watershed:'watershed',monitoring:'monitoring',usgs:'usgs'})[key]+'?'+q);if(v===state.version){if(key==='weather')R.monthly(value,state.year);state[key]=value;}}catch(e){if(v===state.version){state[key]=null;state.errors[key]=e.message;}}finally{if(v===state.version){state.pending.delete(key);refresh();}}}));if(v!==state.version)return;state.loading=false;refresh();bindRecovery();if(['water','climate'].includes(state.route))render(state.route);}

 function csv(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x))rows.push(row);row=[];field='';}else field+=c;}if(field||row.length){row.push(field);rows.push(row);}const headers=rows.shift()||[];return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])));}
 function parseStations(rows){return rows.map(r=>({id:r.MonitoringLocationIdentifier,name:r.MonitoringLocationName,type:r.MonitoringLocationTypeName,lat:+r.LatitudeMeasure,lon:+r.LongitudeMeasure,source:r.OrganizationFormalName})).filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon));}
 function parseResults(rows){return rows.filter(r=>['pH','Dissolved oxygen (DO)','Turbidity','Nitrate + Nitrite','Nitrate','Specific conductance','Temperature, water'].includes(r.CharacteristicName)&&r.ActivityMediaName==='Water'&&r.ResultMeasureValue.trim()!==''&&Number.isFinite(+r.ResultMeasureValue)).map(r=>({station:r.MonitoringLocationIdentifier,parameter:r.CharacteristicName,value:+r.ResultMeasureValue,unit:r['ResultMeasure/MeasureUnitCode'],date:r.ActivityStartDate,fraction:r.ResultSampleFractionText,status:r.ResultStatusIdentifier,qualifier:r.MeasureQualifierCode,detection:r.ResultDetectionConditionText,source:r.OrganizationFormalName}));}
 function km(lat,lon){return MesoraEngine.distance(state,{lat,lon});}
 function inside(point,ring){let hit=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>point[1])!==(b[1]>point[1])&&point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;}
 function countyAt(lat,lon){for(const f of GEO.features){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;if(polys.some(poly=>inside([lon,lat],poly[0])&&!poly.slice(1).some(r=>inside([lon,lat],r))))return f.properties.GEOID;}return null;}
 function validateBoundary(obj){if(obj.type==='FeatureCollection'&&obj.features?.length!==1)throw Error('Upload one farm feature at a time.');const g=obj.type==='Feature'?obj.geometry:obj.type==='FeatureCollection'?obj.features?.[0]?.geometry:obj;if(!g||!['Polygon','MultiPolygon'].includes(g.type))throw Error('Upload a GeoJSON Polygon or MultiPolygon in WGS84 coordinates.');const polys=g.type==='Polygon'?[g.coordinates]:g.coordinates;let count=0,area=0,all=[];for(const poly of polys){for(let r=0;r<poly.length;r++){const ring=poly[r];if(ring.length<4||JSON.stringify(ring[0])!==JSON.stringify(ring.at(-1)))throw Error('Polygon rings must be closed with at least three corners.');const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);for(let i=0;i<ring.length-1;i++)for(let j=i+2;j<ring.length-1;j++){if(i===0&&j===ring.length-2)continue;const a=ring[i],b=ring[i+1],c=ring[j],d=ring[j+1];if(cross(a,b,c)*cross(a,b,d)<0&&cross(c,d,a)*cross(c,d,b)<0)throw Error('Boundary edges must not cross.');}let sum=0;for(let i=0;i<ring.length;i++){const [lon,lat]=ring[i];if(!Number.isFinite(lon)||!Number.isFinite(lat)||Math.abs(lon)>180||Math.abs(lat)>85)throw Error('Invalid WGS84 coordinates');const next=ring[(i+1)%ring.length];sum+=(next[0]-lon)*Math.PI/180*(2+Math.sin(lat*Math.PI/180)+Math.sin(next[1]*Math.PI/180));all.push([lon,lat]);count++;}area+=(r===0?1:-1)*Math.abs(sum)*6371008.8**2/2;}}
 if(count>2000||area<=0||area>5e9)throw Error('Boundary must contain at most 2,000 vertices and a positive area under 500,000 ha.');return {geometry:g,areaHa:area/10000,lon:all.reduce((s,p)=>s+p[0],0)/all.length,lat:all.reduce((s,p)=>s+p[1],0)/all.length};}
 function outerBoundary(input){const pts=[...new Map(input.map(p=>[p.join(','),p])).values()].sort((a,b)=>a[0]-b[0]||a[1]-b[1]);if(pts.length<3)throw Error('Select at least three different corners.');const cross=(o,a,b)=>(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]),lower=[],upper=[];for(const p of pts){while(lower.length>=2&&cross(lower.at(-2),lower.at(-1),p)<=0)lower.pop();lower.push(p);}for(const p of [...pts].reverse()){while(upper.length>=2&&cross(upper.at(-2),upper.at(-1),p)<=0)upper.pop();upper.push(p);}const ring=lower.slice(0,-1).concat(upper.slice(0,-1));return [...ring,ring[0]];}
 function selectFarm(lat,lon,name,boundary=null){state.lat=lat;state.lon=lon;state.name=name||'Selected agricultural location';state.county=countyAt(lat,lon);state.region=state.county?DB.counties[state.county].state:'Unknown';state.boundary=boundary;state.inputs.ph=null;state.results=null;state.attempted=false;state.weather=null;state.soil=null;state.watershed=null;state.monitoring=null;state.usgs=null;state.wq=null;if(marker)marker.setLatLng([lat,lon]);if(map&&boundaryLayer){boundaryLayer.remove();boundaryLayer=null;}if(map&&boundary){boundaryLayer=L.geoJSON(boundary,{style:{color:'#28dfab',weight:2,fillOpacity:.12}}).addTo(map);map.fitBounds(boundaryLayer.getBounds());}updateFarmSummary();loadEvidence();}
 const tabs=[['explore','Explore'],['water','Water'],['infrastructure','Data centers'],['climate','Climate Analysis'],['planner','Rotation Planner'],['compare','Compare'],['sources','Sources']];
 function shell(title,subtitle,content){return `<div class="workspace"><div class="workspace-bar"><a href="#explore" class="farm-chip">${html(state.name)}<small>${num(state.lat,4)}, ${num(state.lon,4)} · ${state.boundary?num(state.areaHa)+' ha drawn':num(state.areaHa)+' ha entered'}</small></a><nav class="workspace-nav" aria-label="Analysis areas">${tabs.map(([k,t])=>`<a href="#${k}" ${state.route===k?'aria-current="page"':''}>${t}</a>`).join('')}</nav></div>${title?`<div class="workspace-title"><div><span class="eyebrow">MESORA / FIELD SHIFT</span><h1>${title}</h1></div><p>${subtitle}</p></div>`:''}${content}</div>`;}
 function statusContent(){const names={weather:'NASA weather',soil:'soil reference',watershed:'watershed',monitoring:'USGS stations',usgs:'USGS observations',wq:'water-quality stations'};if(state.loading)return `<span class="loading-dot"></span> Loading ${[...(state.pending||[])].map(k=>names[k]).join(', ')}… ${state.weather?'Weather is ready; the planner is available.':''}`;const missing=Object.keys(state.errors||{});return missing.length?`<span>${missing.map(k=>names[k]).join(', ')} could not load. Other available data can still be used.</span> <button class="retry-evidence text-cta">Retry data</button> <button class="demo-evidence text-cta">Open ready-to-use Union County demo</button>`:'<span class="ready-dot"></span> Available source data loaded for this location.';}
 function status(){return `<div class="data-status" id="source-status" role="status">${statusContent()}</div>`;}
 function bindRecovery(){document.querySelectorAll('.retry-evidence').forEach(b=>b.onclick=()=>{MesoraData.clear();loadEvidence().then(()=>render(state.route));});document.querySelectorAll('.demo-evidence').forEach(b=>b.onclick=()=>{selectFarm(34.98,-80.55,'Union County demonstration area');render(state.route);});}

 function updateFarmSummary(){const host=el('#farm-summary');if(host)host.innerHTML=`<strong>${html(state.name)}</strong><p>${num(state.lat,4)}, ${num(state.lon,4)}<br>${state.county?html(DB.counties[state.county].name+', '+state.region):'County not resolved'} · ${state.boundary?num(state.areaHa)+' ha boundary':'Point selection; area entered in planner'}</p>${status()}<a href="#water" class="button small">Review environmental evidence →</a><a href="#planner" class="text-cta">Continue to rotation planner →</a>`;}
 const layerDefs={smap:{name:'NASA SMAP surface soil moisture',id:'SMAP_L4_Analyzed_Surface_Soil_Moisture',level:6,units:'m³/m³',resolution:'9 km model grid',legend:'SMAP_Analyzed_Soil_Moisture_H.svg',type:'Satellite-assimilated estimate'},rain:{name:'NASA GPM IMERG precipitation',id:'IMERG_Precipitation_Rate',level:6,units:'mm/hour',resolution:'0.1° grid',legend:'GPM_Precipitation_Rate_H.svg',type:'Satellite precipitation estimate'},temp:{name:'NASA MODIS daytime land temperature',id:'MODIS_Terra_Land_Surface_Temp_Day',level:7,units:'See NASA legend',resolution:'1 km source grid',legend:'MODIS_Land_Surface_Temp_H.svg',type:'Land-surface temperature; not air temperature'},landsat:{name:'NASA/USGS Landsat WELD historical composite',id:'Landsat_WELD_CorrectedReflectance_Bands157_Global_Annual',level:12,units:'Reflectance composite',resolution:'30 m source imagery',date:'2000-12-01',type:'Historical context, not current land cover'}};
 function explore(){el('#main').innerHTML=shell('', '',`<div class="explore-grid"><aside class="map-sidebar" id="analysis-sidebar"><h2>Select your farm</h2><form id="place-form"><label for="place-search">City, county, address, or farm name</label><div class="search-line"><input id="place-search" placeholder="Monroe, North Carolina"><button class="button small">Search</button></div></form><div id="search-results" role="status"></div><p class="tiny">Click the map to choose a point, or draw/upload a boundary. Search © OpenStreetMap.</p><div class="actions"><button id="draw-boundary" class="button outline small">Outline my field</button><button id="finish-boundary" class="button small" hidden>Finish drawing</button><button id="cancel-boundary" class="text-cta" hidden>Cancel</button></div><label class="upload-label">Upload GeoJSON boundary<input type="file" id="boundary-file" accept=".json,.geojson,application/geo+json"></label><div id="boundary-status" role="status"></div><div id="farm-summary"></div><hr><label for="environment-layer">Environmental layer</label><select id="environment-layer"><option value="none">Satellite basemap only</option><option value="cdl">USDA cropland · 2024</option>${Object.entries(layerDefs).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}<option value="watershed">USGS watershed at selected point</option><option value="stations">Water-quality monitoring stations</option><option value="groundwater">Groundwater monitoring locations</option><option value="drought-official">U.S. Drought Monitor · 2026-11-10</option><option value="aquifers">USGS principal aquifer extents</option><option value="drought">Precipitation departure · county context</option></select><label for="layer-date">NASA imagery date</label><input type="date" id="layer-date" min="2015-04-01" max="2026-11-10" value="${state.date}"><div id="map-legend" class="map-legend">Esri World Imagery · acquisition dates vary · geographic context, not a current farm survey.</div><label class="check"><input type="checkbox" id="dc-layer" checked> Show source-linked infrastructure records</label><p class="tiny">Aquifer extents are regional context, not proof that two users share groundwater. ${link('https://water.usgs.gov/themes/aquifers/','Open USGS aquifer viewer')}</p><a href="#atlas" class="text-cta">Open existing national county atlas ↗</a></aside><div class="map-stage"><button id="sidebar-toggle" class="map-toggle" aria-expanded="true">Hide controls</button><div id="farm-map" aria-label="Interactive satellite farm selection map"></div><div class="map-caption">Select a location → review evidence → generate rotations → compare scenarios</div></div></div>`);
 map=L.map('farm-map',{zoomControl:true}).setView([state.lat,state.lon],11);L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Imagery © Esri, Maxar, Earthstar Geographics'}).addTo(map);marker=L.circleMarker([state.lat,state.lon],{radius:8,color:'#fff',weight:3,fillColor:'#167b63',fillOpacity:1}).addTo(map).bindPopup('Selected analysis point');if(state.boundary)boundaryLayer=L.geoJSON(state.boundary,{style:{color:'#28dfab',weight:2}}).addTo(map);const dcLayer=L.layerGroup().addTo(map);RECORDS.forEach(r=>L.circleMarker([r.latitude,r.longitude],{radius:5,color:'#c97335',weight:1,fillOpacity:.9}).bindPopup(`<b>${html(r.title)}</b><br>Public source record; location precision varies.<br>${link(r.sourceUrl,'Evidence')}<br>Shared supply: unknown`).addTo(dcLayer));map.on('click',e=>{if(drawing){points.push([e.latlng.lng,e.latlng.lat]);if(boundaryLayer)boundaryLayer.remove();boundaryLayer=L.polyline(points.map(p=>[p[1],p[0]]),{color:'#28dfab'}).addTo(map);el('#boundary-status').textContent=points.length+' corners selected';}else selectFarm(e.latlng.lat,e.latlng.lng);});
 el('#sidebar-toggle').onclick=()=>{const hidden=el('#analysis-sidebar').hidden;el('#analysis-sidebar').hidden=!hidden;el('#sidebar-toggle').textContent=hidden?'Hide controls':'Show controls';el('#sidebar-toggle').setAttribute('aria-expanded',String(hidden));el('.explore-grid').classList.toggle('collapsed',!hidden);map.invalidateSize();};el('#dc-layer').onchange=e=>e.target.checked?dcLayer.addTo(map):dcLayer.remove();el('#environment-layer').onchange=e=>setLayer(e.target.value);el('#layer-date').onchange=e=>{state.date=e.target.value;setLayer(activeLayer);};el('#draw-boundary').onclick=()=>{drawing=true;points=[];map.doubleClickZoom.disable();el('#finish-boundary').hidden=false;el('#cancel-boundary').hidden=false;el('#boundary-status').textContent='Click the corners around your field, then Finish. You can use a single map point instead.';};el('#cancel-boundary').onclick=()=>{drawing=false;map.doubleClickZoom.enable();points=[];if(boundaryLayer)boundaryLayer.remove();el('#finish-boundary').hidden=true;el('#cancel-boundary').hidden=true;el('#boundary-status').textContent='Drawing cancelled.';};el('#finish-boundary').onclick=()=>{try{let g={type:'Polygon',coordinates:[[...points,points[0]]]},repaired=false;let b;try{b=validateBoundary(g);}catch(error){if(points.length<3)throw Error('Select at least three corners, or click the map once to use a point.');const ring=outerBoundary(points);g={type:'Polygon',coordinates:[ring]};b=validateBoundary(g);repaired=true;}state.areaHa=b.areaHa;drawing=false;map.doubleClickZoom.enable();el('#finish-boundary').hidden=true;el('#cancel-boundary').hidden=true;selectFarm(b.lat,b.lon,'Drawn farm boundary',g);el('#boundary-status').textContent=num(b.areaHa)+' ha approximate area'+(repaired?' · Crossing clicks were reordered into an outer boundary. Review it on the map.':'');}catch(e){el('#boundary-status').textContent=e.message;}};el('#boundary-file').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>1000000)throw Error('Use a GeoJSON file smaller than 1 MB.');const b=validateBoundary(JSON.parse(await file.text()));state.areaHa=b.areaHa;selectFarm(b.lat,b.lon,'Uploaded farm boundary',b.geometry);el('#boundary-status').textContent=num(b.areaHa)+' ha approximate area'+(repaired?' · Crossing clicks were reordered into an outer boundary. Review it on the map.':'');}catch(e){el('#boundary-status').textContent=e.message;}};el('#place-form').onsubmit=async e=>{e.preventDefault();el('#search-results').textContent='Searching…';try{const query=el('#place-search').value.trim();const countyMatches=Object.entries(DB.counties).filter(([id,c])=>(c.name+', '+c.state).toLowerCase().includes(query.toLowerCase())).slice(0,8);let results=countyMatches.map(([id,c])=>({lat:c.lat,lon:c.lon,display_name:c.name+', '+c.state,county:id}));if(!results.length)results=await api('geocode?q='+encodeURIComponent(query));el('#search-results').innerHTML=results.length?results.map((r,i)=>`<button class="search-result" data-i="${i}">${html(r.display_name)}</button>`).join(''):'No matching place. Try a city or click the map.';el('#search-results').querySelectorAll('button').forEach(b=>b.onclick=()=>{const r=results[+b.dataset.i];selectFarm(+r.lat,+r.lon,r.display_name.split(',').slice(0,2).join(','));map.setView([+r.lat,+r.lon],12);});}catch(e){el('#search-results').textContent=e.message+'; you can still select the map.';}};updateFarmSummary();bindRecovery();if(!state.weather&&!state.loading&&!state.attempted)loadEvidence();}
 async function setLayer(key){activeLayer=key;if(overlay){overlay.remove();overlay=null;}const legend=el('#map-legend');if(key==='none'){legend.textContent='Esri World Imagery · acquisition dates vary.';return;}try{if(layerDefs[key]){const d=layerDefs[key],date=d.date||state.date;overlay=L.tileLayer(`https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/${d.id}/default/${date}/GoogleMapsCompatible_Level${d.level}/{z}/{y}/{x}.${key==='landsat'?'jpeg':'png'}`,{maxNativeZoom:d.level,maxZoom:19,opacity:.75,attribution:'NASA GIBS'}).addTo(map);legend.innerHTML=`<b>${d.name}</b><p>${date} · ${d.units} · ${d.resolution}<br>${d.type}. Coarser than a farm; colors are not field samples.</p>${d.legend?`<img src="https://gibs.earthdata.nasa.gov/legends/${d.legend}" alt="NASA layer color legend">`:''}${link('https://gibs.earthdata.nasa.gov/layer-metadata/v1.0/'+d.id+'.json','Dataset metadata')}`;overlay.on('tileerror',()=>{if(activeLayer===key)legend.innerHTML+='<p>One or more tiles are unavailable for this date or area.</p>';});}
 else if(key==='cdl'){const b=map.getBounds(),bbox=[b.getWest(),b.getSouth(),b.getEast(),b.getNorth()].join(',');const url='https://pdi.scinet.usda.gov/image/rest/services/CDL_WM/ImageServer/exportImage?'+new URLSearchParams({bbox,bboxSR:'4326',imageSR:'3857',size:'1024,1024',format:'png',f:'image',adjustAspectRatio:'false',mosaicRule:JSON.stringify({where:'Year=2024'}),renderingRule:JSON.stringify({rasterFunction:'croptypes'})});overlay=L.imageOverlay(url,b,{opacity:.65}).addTo(map);legend.innerHTML=`USDA CDL · 2024 · categorical crop classes · 30 m service pixels. Extent fixed to this view; reselect layer after panning. ${link('https://www.nass.usda.gov/Research_and_Science/Cropland/metadata/metadata_Cropland-Data-Layer-2024.htm','Metadata and class legend')}`;overlay.on('error',()=>legend.textContent='USDA cropland imagery unavailable for this request.');}
 else if(key==='aquifers'){overlay=L.vectorGrid.protobuf('https://d1el80s3n6jq7s.cloudfront.net/aquifer-tiles/{z}/{x}/{y}.pbf',{vectorTileLayerStyles:{'principal-aquifers':{weight:1,color:'#7f65ad',fill:true,fillColor:'#9b8cba',fillOpacity:.25}},interactive:true,maxNativeZoom:8,maxZoom:19,attribution:'USGS principal aquifers'}).addTo(map);overlay.on('click',e=>L.popup().setLatLng(e.latlng).setContent(html(e.layer.properties.AQ_NAME||'Principal aquifer')).openOn(map));legend.innerHTML='USGS principal aquifer extents · regional vector boundaries · viewer updated 2026-10-15. Purple areas are mapped principal aquifers. Absence of a polygon does not mean groundwater is absent. '+link('https://water.usgs.gov/themes/aquifers/','Official source');}
 else if(key==='drought-official'){const d=await data('drought');if(activeLayer!==key)return;const colors=['#ffff00','#fcd37f','#ffaa00','#e60000','#730000'];overlay=L.geoJSON(d,{style:f=>({color:colors[f.properties.DM],weight:.5,fillColor:colors[f.properties.DM],fillOpacity:.45}),onEachFeature:(f,l)=>l.bindPopup('U.S. Drought Monitor D'+f.properties.DM+' · 2026-11-10')}).addTo(map);legend.innerHTML='<b>U.S. Drought Monitor · 2026-11-10</b><p>Regional synthesis, not farm-scale soil moisture.</p>'+colors.map((c,i)=>'<span class="legend-chip" style="border-left:12px solid '+c+'">D'+i+'</span>').join('')+'<p>D0 abnormally dry; D1 moderate; D2 severe; D3 extreme; D4 exceptional drought. '+link('https://droughtmonitor.unl.edu/','Official map')+'</p>';}
 else if(key==='watershed'){if(!state.watershed?.features?.length)throw Error('Watershed data not available yet.');overlay=L.geoJSON(state.watershed,{style:{color:'#32b9ff',fillOpacity:.08},onEachFeature:(f,l)=>l.bindPopup(html(f.properties.name||f.properties.NAME||'HUC12 watershed'))}).addTo(map);legend.innerHTML='USGS WBD · HUC12 boundary at selected point · vector hydrography. Same watershed does not establish a shared water supply.';}
 else if(key==='stations'||key==='groundwater'){const points=key==='stations'?(state.wq?.stations||[]).map(s=>({lat:s.lat,lon:s.lon,name:s.name,id:s.id})):(state.monitoring?.features||[]).filter(f=>f.properties.site_type_code==='GW').map(f=>({lat:f.geometry.coordinates[1],lon:f.geometry.coordinates[0],name:f.properties.monitoring_location_name,id:f.properties.id}));if(!points.length)throw Error('No monitoring locations loaded in this area.');overlay=L.layerGroup(points.map(s=>L.circleMarker([s.lat,s.lon],{radius:5,color:key==='stations'?'#4f74d8':'#845ab0',fillOpacity:.8}).bindPopup(`${html(s.name)}<br>${html(s.id)}<br>Regional context; connection unverified`))).addTo(map);legend.textContent=(key==='stations'?'Water Quality Portal':'USGS groundwater')+' · station points · snapshot retrieved 2026-11-15 or current query. Monitoring dates vary; see Water near your farm.';}
 else if(key==='drought'){if(!state.weather||!state.county)throw Error('Weather and county boundary are needed.');const annual=annualWeather(),avg=annual.filter(x=>x.year<2025).reduce((s,x)=>s+x.rain,0)/10,cur=annual.find(x=>x.year===2025),departure=(cur.rain/avg-1)*100;const f=GEO.features.find(f=>f.properties.GEOID===state.county);overlay=L.geoJSON(f,{style:{color:departure<0?'#a87728':'#299cbd',fillOpacity:.32}}).addTo(map);legend.textContent=`Derived precipitation departure: ${num(departure)}% in 2025 versus 2015–2024 at the selected NASA grid point. County outline is context only, not spatially uniform drought classification. This is not the U.S. Drought Monitor.`;}}
 catch(e){legend.textContent=e.message;}}
 function chart(rows,key,unit,label){if(rows.length<2)return '<p class="empty">At least two comparable observations are needed for a trend chart.</p>';const vals=rows.map(r=>+r[key]),low=Math.min(...vals),high=Math.max(...vals),span=high-low||1;return `<div class="chart" role="img" aria-label="${html(label)}"><svg viewBox="0 0 720 190" preserveAspectRatio="none"><line x1="40" x2="700" y1="155" y2="155" stroke="#cad9d2"/><polyline fill="none" stroke="#147a67" stroke-width="2.5" points="${rows.map((r,i)=>`${40+660*i/(rows.length-1)},${145-120*(r[key]-low)/span}`).join(' ')}"/>${rows.map((r,i)=>`<circle cx="${40+660*i/(rows.length-1)}" cy="${145-120*(r[key]-low)/span}" r="3" fill="#147a67"><title>${html(r.label||r.year||r.date)}: ${num(r[key],2)} ${html(unit)}</title></circle>`).join('')}<text x="5" y="20">${num(high)}</text><text x="5" y="150">${num(low)}</text><text x="40" y="178">${html(rows[0].label||rows[0].year||rows[0].date)}</text><text x="610" y="178">${html(rows.at(-1).label||rows.at(-1).year||rows.at(-1).date)}</text></svg><small>${html(label)} · ${html(unit)} · hover a point for its value</small></div>`;}
 function annualWeather(){return Array.from({length:11},(_,i)=>{const year=2015+i,m=R.monthly(state.weather,year);return {year,rain:m.reduce((s,x)=>s+x.rain,0),temp:m.reduce((s,x)=>s+x.t*x.days,0)/m.reduce((s,x)=>s+x.days,0)};});}
 function soilCard(){const table=state.soil?.Table,rows=table?.slice(1)||[];if(!rows.length)return `<p class="empty">No soil-map record is loaded here yet. Your own soil-test values can still be entered in the planner.</p>`;return `<p>${html(rows[0][1])}</p><div class="table-wrap"><table><thead><tr><th>Component</th><th>Map-unit share</th><th>Depth</th><th>pH</th><th>Clay / sand</th><th>Drainage</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${html(r[2])}</td><td>${html(r[3])}%</td><td>${html(r[5])}–${html(r[6])} cm</td><td>${html(r[7]||'Unknown')}</td><td>${html(r[8])}% / ${html(r[9])}%</td><td>${html(r[4])}</td></tr>`).join('')}</tbody></table></div><p class="tiny">NRCS SSURGO map-unit components at the analysis point, retrieved ${atDemo()?'2026-11-15':'for this request'}. Not a laboratory soil test or farm-wide average. Organic matter is available in the downloaded record. ${link('https://sdmdataaccess.sc.egov.usda.gov/','Source')}</p>`;}
 function water(){const measured=new Set((state.wq?.measurements||[]).map(m=>m.station));const stations=[...(state.wq?.stations||[])].filter(s=>s.name&&!['None','MISSING'].includes(s.name)).sort((a,b)=>(measured.has(b.id)-measured.has(a.id))||((/stream|river|lake|reservoir/i.test(b.type)?1:0)-(/stream|river|lake|reservoir/i.test(a.type)?1:0))||km(a.lat,a.lon)-km(b.lat,b.lon)).slice(0,60);const first=stations.find(s=>measured.has(s.id))||stations[0];const records=RECORDS.map(r=>({...r,distance:km(r.latitude,r.longitude)})).filter(r=>r.distance<200).sort((a,b)=>a.distance-b.distance).slice(0,15),reported=DC.map(r=>({...r,distance:km(r.lat,r.lon)})).filter(r=>r.distance<200).sort((a,b)=>a.distance-b.distance);el('#main').innerHTML=shell('Water near your farm','Review sampled water quality, soil conditions, and the sources that support your plan.',`${status()}<div class="two-col"><section class="panel"><h2>Water-quality observations</h2><p>Nearby monitoring is regional context. No station is assumed to sample your irrigation supply.</p><label for="wq-station">Monitoring station</label><select id="wq-station">${stations.map(s=>`<option value="${html(s.id)}" ${s.id===first?.id?'selected':''}>${html(s.name)} · ${num(km(s.lat,s.lon))} km${measured.has(s.id)?' · samples available':''}</option>`).join('')}</select><div id="wq-observations"></div>${!stations.length?'<p class="empty">No stations loaded. No water-quality values have been substituted.</p>':''}</section><section class="panel"><h2>Soil & water access</h2>${soilCard()}<h3>Watershed</h3><p>${state.watershed?.features?.length?state.watershed.features.map(f=>html(f.properties.name||f.properties.NAME||f.properties.huc12||'HUC12 watershed')).join(', '):'No watershed returned.'}</p><p>Watershed membership does not prove a common well, aquifer, or utility supply. Farm water entitlement is not inferred from regional withdrawals.</p><h3>USGS monitoring</h3><div class="table-wrap"><table><thead><tr><th>Station</th><th>Parameter</th><th>Value</th><th>Observed</th></tr></thead><tbody>${(state.usgs?.features||[]).filter(f=>['72019','00060','00010','00300'].includes(f.properties.parameter_code)).sort((a,b)=>b.properties.time.localeCompare(a.properties.time)).slice(0,12).map(f=>{const p=f.properties;return `<tr><td>${link('https://waterdata.usgs.gov/monitoring-location/'+p.monitoring_location_id+'/',p.monitoring_location_id)}</td><td>${({'72019':'Depth to water','00060':'Discharge','00010':'Water temperature','00300':'Dissolved oxygen'})[p.parameter_code]}</td><td>${html(p.value)} ${html(p.unit_of_measure)}</td><td>${html(p.time.slice(0,10))}<small>${html(p.approval_status)}</small></td></tr>`;}).join('')||'<tr><td colspan="4">No matching measurements returned.</td></tr>'}</tbody></table></div><p class="tiny">Latest available source records may be old or provisional. Depth-to-water is not an available volume.</p></section></div><section class="panel water-infrastructure-link"><span class="eyebrow">INFRASTRUCTURE & WATER PRESSURE</span><h2>Where do data centers enter the picture?</h2><p>Explore nearby source-linked records and reported consumption, then test additional demand in a clearly labeled scenario.</p><a href="#infrastructure" class="button">Explore data centers →</a></section><div class="actions"><a href="#climate" class="button outline">Next: climate evidence →</a><a href="#planner" class="button">Build rotation options →</a></div>`);if(first){showStation(first.id);el('#wq-station').onchange=e=>showStation(e.target.value);}}
 async function showStation(id){const host=el('#wq-observations');if(!host)return;let rows=(state.wq?.measurements||[]).filter(x=>x.station===id);if(!rows.length&&!atDemo()){host.innerHTML='<p>Retrieving station samples…</p>';try{const raw=await api('water-results?site='+encodeURIComponent(id));rows=parseResults(csv(raw));state.wq.measurements.push(...rows);}catch(e){host.textContent='Samples unavailable: '+e.message;return;}}if(!el('#wq-station')||el('#wq-station').value!==id)return;if(!rows.length){host.innerHTML='<p class="empty">No selected water-quality parameters available for this station in the retrieved period.</p>';return;}const keys=[...new Set(rows.map(r=>[r.parameter,r.unit,r.fraction].join('|')))];host.innerHTML=`<label for="wq-parameter">Parameter, units, and sample fraction</label><select id="wq-parameter">${keys.map((k,i)=>`<option value="${i}">${html(k.split('|').join(' · '))}</option>`).join('')}</select><div id="wq-series"></div><p class="tiny">Source: Water Quality Portal / contributing agency. Sample dates below. Non-detects and qualifiers are retained; unlike units and fractions are not combined. ${link('https://www.waterqualitydata.us/','Portal')}</p>`;const draw=()=>{const key=keys[+el('#wq-parameter').value],list=rows.filter(r=>[r.parameter,r.unit,r.fraction].join('|')===key).sort((a,b)=>a.date.localeCompare(b.date)),numeric=list.filter(r=>!r.detection&&!r.qualifier),parts=key.split('|');el('#wq-series').innerHTML=chart(numeric,'value',parts[1],parts[0])+`<div class="table-wrap"><table><thead><tr><th>Sampling date</th><th>Value</th><th>Units</th><th>Status / qualifier</th></tr></thead><tbody>${list.slice(-18).reverse().map(r=>`<tr><td>${html(r.date)}</td><td>${num(r.value,3)}</td><td>${html(r.unit)}</td><td>${html([r.status,r.qualifier,r.detection].filter(Boolean).join(' / '))}</td></tr>`).join('')}</tbody></table></div><p>${({pH:'pH affects irrigation chemistry, but pH alone does not determine suitability.','Specific conductance':'Conductance provides salinity context. Crop tolerance, sodium adsorption ratio, units, soil and drainage must also be assessed.','Nitrate + Nitrite':'Nitrate plus nitrite may be relevant to nutrient management; confirm the analytical basis before calculating any nitrogen credit.','Turbidity':'Turbidity may indicate filtration needs, but a regional sample cannot diagnose your irrigation equipment.','Dissolved oxygen (DO)':'Dissolved oxygen describes aquatic conditions; it is not an irrigation-water safety score.','Temperature, water':'Water temperature provides sample context; it does not establish irrigation suitability.'})[parts[0]]||'Review this parameter with a water-quality specialist for your actual irrigation supply.'} No change is attributed to a data center.</p>`;};el('#wq-parameter').onchange=draw;draw();}
 function climate(){if(!state.weather){el('#main').innerHTML=shell('Climate Analysis','NASA observations and derived indicators',status()+'<p class="panel">Weather data are not available yet. '+(state.errors?.weather?html(state.errors.weather):'')+'</p>');return;}el('#main').innerHTML=shell('Climate Analysis','Historical observations describe variability and trends. Eleven years of data do not establish long-term climate attribution.',`${status()}<section class="panel"><div class="form-grid"><label>Compare metric<select id="climate-metric"><option value="rain">Annual precipitation · mm</option><option value="temp">Annual mean air temperature · °C</option></select></label><label>First year<select id="climate-start">${Array.from({length:10},(_,i)=>`<option>${2015+i}</option>`).join('')}</select></label><label>Last year<select id="climate-end">${Array.from({length:10},(_,i)=>`<option ${i===9?'selected':''}>${2016+i}</option>`).join('')}</select></label></div><div id="climate-series"></div><details><summary>View monthly observations and reference evapotranspiration</summary><label>Recorded year<select id="monthly-year">${Array.from({length:11},(_,i)=>`<option ${i===10?'selected':''}>${2015+i}</option>`).join('')}</select></label><div id="monthly-series"></div></details><p class="tiny">NASA POWER daily inputs, aggregated by calendar month/year. Meteorology approximately 0.5° × 0.625°; solar inputs coarser. NASA model/reanalysis and satellite-derived products, not a farm weather station. ${link('https://power.larc.nasa.gov/docs/services/api/temporal/daily/','Source & parameter documentation')}</p></section><section class="panel"><h2>Soil moisture and precipitation imagery</h2><p>SMAP L4 shows satellite-assimilated soil moisture on a 9 km model grid. IMERG shows precipitation estimates on a 0.1° grid. Inspect the dated layers in Explore. Numeric SMAP time-series extraction is not connected; no moisture values are inferred from map colors.</p><a class="button outline" href="#explore">Inspect NASA layers →</a><p>Lower precipitation can increase supplementary irrigation. Evapotranspiration also depends on radiation, humidity, wind and temperature. The planning model uses these NASA inputs with FAO reference equations. It does not turn a short anomaly into a climate-change claim.</p></section><a href="#planner" class="button">Use this evidence in the planner →</a>`);const draw=()=>{const a=+el('#climate-start').value,b=+el('#climate-end').value,key=el('#climate-metric').value,rows=annualWeather().filter(x=>x.year>=a&&x.year<=b);el('#climate-series').innerHTML=a>=b?'<p>Choose an end year after the start year.</p>':chart(rows,key,key==='rain'?'mm':'°C',key==='rain'?'Annual precipitation':'Annual mean air temperature')+`<p>Linear change over this selected window: <b>${num(R.trend(rows,key),2)} ${key==='rain'?'mm':'°C'} per year</b>. This descriptive fit is not a climate projection or a significance test.</p>`;};['climate-start','climate-end','climate-metric'].forEach(id=>el('#'+id).onchange=draw);const month=()=>{const rows=R.monthly(state.weather,+el('#monthly-year').value);el('#monthly-series').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Month</th><th>Rain</th><th>Air temperature</th><th>Reference ETo</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${m.month}</td><td>${num(m.rain)} mm</td><td>${num(m.t)} °C</td><td>${num(R.eto(m,state.lat,state.weather.geometry.coordinates[2]))} mm/day · estimated</td></tr>`).join('')}</tbody></table></div>`;};el('#monthly-year').onchange=month;draw();month();}
 function planner(){const i=state.inputs;el('#main').innerHTML=shell('Rotation Planner','Generate multiyear options that satisfy your crop, calendar, and seasonal irrigation constraints.',`${status()}<form id="rotation-form"><div class="two-col"><section class="panel"><h2>Your farm and constraints</h2><div class="form-grid"><label>Farm size · hectares<input name="area" type="number" min=".01" max="500000" step="any" value="${state.areaHa}" required></label><label>Planning period<select name="years">${[2,3,4].map(n=>`<option ${i.years===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Seasonal irrigation available · mm<input name="budget" type="number" min="0" max="2000" step="any" value="${i.budget}" required></label><label>Reference weather year<select name="year">${Array.from({length:10},(_,n)=>`<option ${state.year===2016+n?'selected':''}>${2016+n}</option>`).join('')}</select></label><label>Most recent crop<select name="previous"><option value="unknown">Not specified</option>${Object.entries(R.crops).map(([k,c])=>`<option value="${k}" ${i.previous.at(-1)===k?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Earlier crop<select name="earlier"><option value="unknown">Not specified</option>${Object.entries(R.crops).map(([k,c])=>`<option value="${k}" ${i.previous.length>1&&i.previous[0]===k?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Soil drainage<select name="drainage"><option value="unknown">Not confirmed</option><option value="well" ${i.drainage==='well'?'selected':''}>Well drained</option><option value="poor" ${i.drainage==='poor'?'selected':''}>Poorly drained</option></select></label><label>Your measured soil pH, if known<input name="ph" type="number" min="3" max="10" step=".1" value="${i.ph??''}" placeholder="Leave blank if unknown"></label></div><details><summary>View the soil map reference</summary>${soilCard()}</details><p class="tiny">1 mm over 1 hectare = 10 m³. Enter a water budget you are authorized and able to use. The planner does not infer an entitlement.</p><label class="check"><input type="checkbox" name="quality" ${i.qualityConcern?'checked':''}> I have a documented concern with my actual irrigation supply that needs review</label><label>Water-access / quality notes<textarea name="accessNotes" placeholder="For example: permit limit or a laboratory report for my well">${html(i.accessNotes||'')}</textarea></label><p class="tiny">Planting calendars are reference defaults. Check local planting dates, varieties and soil conditions before acting on a plan.</p>${['AK','HI','Unknown'].includes(state.region)?'<label class="check"><input type="checkbox" name="confirmRegion">I have checked these reference calendars for this location</label>':''}</section><section class="panel"><h2>Choose crops and priorities</h2><p>Checked crops are eligible; unchecked crops are excluded. The optimizer uses five field crops with documented reference coefficients. The existing 20-crop library remains available for broader water comparisons.</p><div class="crop-choices">${Object.entries(R.crops).map(([k,c])=>`<label class="check"><input type="checkbox" name="crop" value="${k}" ${i.allowed.includes(k)?'checked':''}>${c.name} <small>${c.family} · ${c.season}</small></label>`).join('')}</div><label class="check"><input type="checkbox" name="cover" ${i.cover?'checked':''}> Compare rotations with cereal rye cover crops where the calendar permits</label><div class="priorities">${[['water','Conserve irrigation water'],['soil','Diversity and living cover'],['resilience','Drought resilience'],['productivity','Agronomic readiness, not predicted yield']].map(([k,t])=>`<label>${t}<select name="priority-${k}">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${i.weights[k]===n?'selected':''}>${n===0?'Off':n===5?'Highest priority':n}</option>`).join('')}</select></label>`).join('')}</div><p class="tiny">Scores rank the entered preferences. They are not success probabilities. Quantitative harvest predictions are omitted from this optimizer.</p><button class="button" type="submit" ${!state.weather?'disabled':''}>Generate rotation options →</button><div id="planner-error" role="alert"></div><p id="weather-ready">${state.weather?'NASA weather is ready. You can calculate now.':'Loading NASA weather for this location…'}</p><a href="#sources" class="text-cta">Review formulas and agronomic references ↗</a></section></div></form><div id="rotation-results"></div>`);el('#rotation-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),allowed=f.getAll('crop');if(allowed.length<2){el('#planner-error').textContent='Choose at least two crops to avoid consecutive repeats.';return;}state.areaHa=+f.get('area');state.year=+f.get('year');state.inputs={...state.inputs,years:+f.get('years'),budget:+f.get('budget'),previous:[f.get('earlier'),f.get('previous')].filter(x=>x!=='unknown'),allowed,excluded:Object.keys(R.crops).filter(x=>!allowed.includes(x)),cover:f.has('cover'),ph:f.get('ph')===''?null:+f.get('ph'),drainage:f.get('drainage'),qualityConcern:f.has('quality'),accessNotes:f.get('accessNotes'),confirmRegion:f.has('confirmRegion'),weights:Object.fromEntries(['water','soil','resilience','productivity'].map(k=>[k,+f.get('priority-'+k)]))};try{state.results=run({});el('#planner-error').textContent='';el('#rotation-results').innerHTML=resultCards(state.results);bindResults();el('#rotation-results').scrollIntoView({behavior:'smooth'});}catch(e){el('#planner-error').textContent=e.message;}};if(state.results){el('#rotation-results').innerHTML=resultCards(state.results);bindResults();}}
 function run(scenario){return R.optimize({...state.inputs,weather:R.monthly(state.weather,state.year),lat:state.lat,elevation:state.weather.geometry.coordinates[2]||180,areaHa:state.areaHa,state:state.region,scenario});}
 function diverseTop(r){const used=new Set(),out=[];for(const p of r.strategies){const signature=[...p.seq].sort().join('-')+'-'+p.coverCount;if(used.has(signature))continue;used.add(signature);out.push(p);if(out.length===3)break;}return out;}
 function resultCards(r){if(!r.strategies.length)return `<section class="panel"><h2>No rotation meets all selected constraints</h2><p>${html(r.message||'Try a larger irrigation budget, additional eligible crops, or a different planning period. No infeasible sequence has been labeled a recommendation.')}</p><p>Rejected for water limits: ${r.rejected.water}; calendar: ${r.rejected.calendar}; previous crop: ${r.rejected.history}; drainage: ${r.rejected.drainage}.</p></section>`;const top=diverseTop(r);return `<section class="result-intro"><h2>${top.length} rotation options to review</h2><p>${r.strategies.length} candidates satisfy the modeled calendar and irrigation constraints. ${top.length<3?'Fewer than three options are feasible; constraints were not silently relaxed.':''} Each year reuses the same reference weather, not a future forecast. Tied scores do not establish a uniquely best order. Every plan still needs local agronomic review. Year labels refer to harvest cycles; winter crops start in the preceding autumn.</p><a href="#compare" class="button outline">Compare environmental scenarios →</a></section><div class="rotation-options">${top.map((p,n)=>`<article class="rotation-option"><div class="option-title"><span>OPTION ${String.fromCharCode(65+n)}</span><strong>${num(p.score,1)} / 100 <small>preference score</small></strong></div><h3>${p.seq.map(k=>R.crops[k].name).join(' → ')}</h3><div class="option-calendar">${p.seasons.map(s=>`<div><span>YEAR ${s.year}</span><b>${s.name}</b><small>${s.calendar}</small>${s.cover?'<small>Preceded by rye cover · Nov–Mar</small>':''}<strong>${num(s.irrigation)} mm irrigation</strong></div>`).join('')}</div><p><b>Why it ranks here:</b> ${num(p.total)} mm total modeled supplementary irrigation; ${p.familyChanges} crop-family changes; ${p.coverCount} cover-crop periods. Weighted water, diversity, drought-reference, and readiness indicators determine the order.</p><details><summary>Evidence, score breakdown and uncertainty</summary><p>${Object.entries(p.components).map(([k,v])=>`${k}: ${num(v*100)} / 100`).join(' · ')}</p><p>Water volume over ${num(state.areaHa)} ha: ${num(p.m3)} m³ across the planning period. Irrigation estimate uses NASA reference weather, FAO ETo, stage coefficients and 70% effective-rainfall assumption.</p><ul>${p.warnings.map(w=>`<li>${html(w)}</li>`).join('')}</ul><p>${link(R.sources.fao,'FAO method')} · ${link(R.sources.rotation,'NC State rotation guidance')}</p></details><button class="text-cta save-plan" data-id="${p.id}">Download this plan ↓</button></article>`).join('')}</div>`;}
 function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function bindResults(){document.querySelectorAll('.save-plan').forEach(b=>b.onclick=()=>{const p=state.results.strategies.find(x=>x.id===b.dataset.id);download('mesora-rotation-'+p.id+'.json',{farm:{name:state.name,lat:state.lat,lon:state.lon,areaHa:state.areaHa,boundary:state.boundary},inputs:state.inputs,weatherYear:state.year,plan:p,method:state.results.method,sources:R.sources,limitations:'Reference-date planning, not a forecast or validated yield/soil outcome'});});}
 function compare(){el('#main').innerHTML=shell('Compare','Translate observed environmental context and explicitly simulated stress into changes in feasible rotations.',`${status()}<section class="panel"><h2>Compare your farm under water pressure</h2><p>Start with NASA’s recorded ${state.year} weather, then compare a climate-stress scenario and added water demand. These are planning simulations, not forecasts.${state.sim.report?` The demand input below starts from a 25% increase in ${html(state.sim.report)}’s reported consumption.`:' Use reported data from the <a href="#infrastructure">Data centers</a> page or enter a hypothetical development.'}</p><form id="scenario-form"><div class="form-grid"><label>Climate Stress: temperature change · °C<input name="warming" type="number" min="0" max="6" step=".5" value="${state.sim.warming}"></label><label>Climate Stress: rainfall change · %<input name="rainChange" type="number" min="-80" max="30" step="5" value="${state.sim.rainChange}"></label><label>Additional annual infrastructure demand · m³<input name="demandM3" type="number" min="0" max="1000000000" value="${state.sim.demandM3}"></label><label>Cooling efficiency: water saved · %<input name="coolingSavings" type="number" min="0" max="100" value="${state.sim.coolingSavings*100}"></label><label>Reclaimed-water share · %<input name="reclaimed" type="number" min="0" max="100" value="${state.sim.reclaimed*100}"></label><label>Demand during growing period · %<input name="seasonal" type="number" min="0" max="100" value="${state.sim.seasonal*100}"></label><label>Assumed supply source<select name="supply"><option>Unspecified</option><option>Municipal supply</option><option>Surface water</option><option>Groundwater</option><option>Reclaimed water</option></select></label><label>Share of added demand charged to this farm · %<input name="farmShare" type="number" min="0" max="100" step=".1" value="${state.sim.farmShare*100}"></label></div><label class="check"><input type="checkbox" name="shared" ${state.sim.shared?'checked':''}>Apply the added demand to my farm’s water budget for this simulation</label><p class="tiny">Select the box to test a shared-water scenario. Leave it off to compare climate alone. Your entered share converts additional demand into a reduction in the farm’s irrigation budget.</p><button class="button" type="submit" ${!state.weather?'disabled':''}>Compare scenarios →</button><p id="weather-ready">${state.weather?'NASA weather is ready. You can compare now.':'Loading NASA weather…'}</p></form></section><div id="scenario-results"></div>`);el('#scenario-form').onsubmit=e=>{e.preventDefault();if(!state.weather){el('#scenario-results').innerHTML='<p class="panel">Weather is still loading. Use the retry control above or open the ready Union County demo.</p>';return;}const f=new FormData(e.target);state.sim={warming:+f.get('warming'),rainChange:+f.get('rainChange'),demandM3:+f.get('demandM3'),coolingSavings:+f.get('coolingSavings')/100,reclaimed:+f.get('reclaimed')/100,seasonal:+f.get('seasonal')/100,farmShare:+f.get('farmShare')/100,shared:f.has('shared'),supply:f.get('supply')};drawCompare();};if(state.weather)drawCompare();}
 function drawCompare(){try{const climate={warming:state.sim.warming,rainChange:state.sim.rainChange},cases=[['Current conditions',{}],['Climate Stress',climate],['Combined Water Stress',state.sim]],runs=cases.map(([name,s])=>({name,r:run(s)}));el('#scenario-results').innerHTML=`<section class="comparison-summary"><div><span>BASELINE IRRIGATION</span><strong>${num(state.inputs.budget)} mm</strong></div><div><span>ASSUMED INFRASTRUCTURE EFFECT</span><strong>−${num(runs[2].r.infra?.mm||0)} mm</strong></div><div><span>REMAINING IN COMBINED SCENARIO</span><strong>${num(runs[2].r.budget??state.inputs.budget)} mm</strong></div></section><div class="scenario-grid">${runs.map(({name,r})=>`<section class="panel"><span class="data-type">${name==='Current conditions'?'HISTORICAL INPUTS + ESTIMATES':'SIMULATED'}</span><h2>${name}</h2><p><b>${num(r.budget??state.inputs.budget)} mm</b> irrigation available per season</p><p>${r.strategies.length} feasible modeled strategies</p>${r.strategies[0]?`<h3>${r.strategies[0].seq.map(k=>R.crops[k].name).join(' → ')}</h3><p>${num(r.strategies[0].total)} mm total supplementary irrigation; score ${num(r.strategies[0].score)}.</p><p>${r.strategies[0].coverCount} rye-cover periods; ${r.strategies[0].familyChanges} family changes.</p>`:'<p>No plan fits the current constraints. Increase available irrigation or change the eligible crop set; no infeasible recommendation is substituted.</p>'}</section>`).join('')}</div><section class="panel"><h3>Why the comparison changes</h3><p>Climate Stress changes only the weather inputs used in estimated crop demand and rainfall. Combined Water Stress also reduces the irrigation budget only under your explicit shared-supply assumption. Actual station samples and satellite images are never changed.</p><p>Simulated growing-season freshwater demand: ${num(runs[2].r.infra?.freshwater||0)} m³ = annual demand × (1 − cooling savings) × (1 − reclaimed share) × seasonal fraction. Farm allocation impact: ${num(runs[2].r.infra?.allocated||0)} m³, or ${num(runs[2].r.infra?.mm||0)} mm across ${num(state.areaHa)} ha.</p><p>${runs[0].r.strategies[0]?.id===runs[2].r.strategies[0]?.id?'The leading sequence does not change under these inputs. A changed scenario need not produce a different winner.':'The leading feasible strategy changes because weather-driven irrigation requirements, the entered budget, or feasibility changed. Soil-diversity indicators are unchanged for an identical sequence.'}</p><div class="table-wrap"><table><thead><tr><th>Baseline top strategy</th>${runs.map(x=>`<th>${x.name}</th>`).join('')}</tr></thead><tbody>${diverseTop(runs[0].r).map(p=>`<tr><td>${p.seq.map(k=>R.crops[k].name).join(' → ')}${p.coverCount?' + cover':''}</td>${runs.map(({r})=>{const idx=r.strategies.findIndex(x=>x.id===p.id),match=r.strategies[idx];return `<td>${match?`Rank ${idx+1} · ${num(match.total)} mm`:'Not feasible under these constraints'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`;}catch(e){el('#scenario-results').innerHTML='<p class="panel">'+html(e.message)+'</p>';}}
 function infrastructure(){const reports=DC.map(d=>({...d,km:km(d.lat,d.lon)})).sort((a,b)=>a.km-b.km),records=RECORDS.map(d=>({...d,km:km(d.latitude,d.longitude)})).sort((a,b)=>a.km-b.km),nearReports=reports.filter(d=>d.km<=200),nearRecords=records.filter(d=>d.km<=200),consumption=nearReports.reduce((sum,d)=>sum+d.consumptionMG,0);el('#main').innerHTML=shell('Data centers & your water','Locate documented infrastructure, see disclosed water demand, and compare an explicitly assumed increase against your farm’s water budget.',`<section class="infrastructure-hero"><div><span class="eyebrow">INFRASTRUCTURE & WATER PRESSURE</span><h2>Nearby does not always mean a shared supply.</h2><p>These are real source-linked records and operator reports. MESORA shows the evidence, then lets you test a clearly stated water-demand scenario.</p><a class="button" href="#compare">Compare added water demand →</a></div><div class="infra-stat"><strong>${nearRecords.length}</strong><span>source-linked records within 200 km</span><strong>${num(consumption,1)} million gal</strong><span>reported annual consumption in that radius · 2025 locality totals</span></div></section><div class="two-col"><section class="panel"><h2>Reported water demand</h2><p>Reporting localities are mapped at approximate city/county centers. They are not facility-level coordinates or measured losses to your farm.</p>${(nearReports.length?nearReports:reports.slice(0,3)).map(d=>`<article class="water-report"><div><span class="data-type">OPERATOR REPORTED · ${d.year}</span><h3>${html(d.name)}</h3><p>${num(d.km)} km from your selected location${d.km>200?' · nearest outside the 200 km search':''}</p></div><div class="report-figures"><div><b>${num(d.consumptionMG)} M gal</b><span>consumed / year</span></div><div><b>${num(d.withdrawalMG)} M gal</b><span>withdrawn / year</span></div></div><p>${html(d.precision)} · Water source / cooling: not established in this water-use table. Farm-supply relationship: <b>Unknown</b>.</p>${link(d.source,'Open reported figures')}<button class="text-cta use-report" data-name="${html(d.name)}" data-consumption="${d.consumptionMG}">Simulate a 25% increase in this reported demand →</button></article>`).join('')}</section><section class="panel"><h2>Infrastructure evidence near this farm</h2><p>Location precision and record status are shown with each source. An agency record alone does not establish present operation or a water-supply connection.</p>${(nearRecords.length?nearRecords:records.slice(0,3)).slice(0,12).map(d=>`<details class="infra-record"><summary>${html(d.title)}<span>${num(d.km)} km · connection unknown${d.km>200?' · outside search radius':''}</span></summary><p>${html(d.summary)}</p><dl><dt>Location</dt><dd>${html(d.locality)} · ${html(d.locationPrecision||'Source-linked location')}</dd><dt>Record status</dt><dd>${html(d.status)} · ${html(d.recordDate||d.verifiedOn)}</dd><dt>Operator / cooling / water source</dt><dd>Not independently established in this record.</dd><dt>Quantified consumption</dt><dd>Unavailable in this record; it is not counted as zero.</dd></dl><p>${html(d.boundary)}</p>${link(d.sourceUrl,d.sourceLabel||'Official source')}</details>`).join('')}<a class="text-cta" href="#explore">Show records on the satellite map →</a></section></div><section class="panel connection-guide"><div><b>Verified connection</b><p>Documented shared supply or relevant hydrological evidence.</p></div><div><b>Potential overlap</b><p>Resource evidence suggests an overlap; distance alone is insufficient.</p></div><div><b>Unknown</b><p>Shared supply is not established for the listed farm relationships.</p></div></section>`);document.querySelectorAll('.use-report').forEach(b=>b.onclick=()=>{state.sim.demandM3=+b.dataset.consumption*3785.411784*.25;state.sim.report=b.dataset.name;state.sim.shared=false;location.hash='compare';});}
 function methods(){const rows=[['NASA POWER','Daily precipitation, temperature, radiation, humidity and wind used in water calculations. 2015–2025; regional grid, not a farm weather station.','https://power.larc.nasa.gov/docs/services/api/temporal/daily/','WEATHER'],['NASA SMAP','Soil-moisture imagery. 9 km model grid; dated map context.','https://smap.jpl.nasa.gov/','SOIL MOISTURE'],['NASA GPM IMERG','Satellite precipitation imagery. 0.1° grid; map date shown in Explore.','https://gpm.nasa.gov/','PRECIPITATION'],['NASA / USGS Landsat and MODIS','Historical Landsat reflectance and dated MODIS land-surface temperature imagery.','https://www.earthdata.nasa.gov/','SATELLITE IMAGERY'],['USDA Cropland Data Layer','2024 categorical crop map. 30 m service pixels.','https://www.nass.usda.gov/Research_and_Science/Cropland/','CROPLAND'],['NRCS SSURGO','Mapped soil components, horizons, pH and drainage at the selected point. These are mapped references, not lab samples.','https://sdmdataaccess.sc.egov.usda.gov/','SOIL'],['USGS Water Data and WBD','Dated stream and groundwater observations, monitoring locations and HUC12 watershed boundaries.','https://api.waterdata.usgs.gov/','WATER'],['Water Quality Portal / reporting agencies','Station samples with dates, units and qualifiers. Nearby stations provide regional context.','https://www.waterqualitydata.us/','WATER QUALITY'],['USGS principal aquifers','Regional mapped aquifer extents.','https://water.usgs.gov/themes/aquifers/','AQUIFERS'],['U.S. Drought Monitor','Regional drought synthesis, snapshot 2026-11-10.','https://droughtmonitor.unl.edu/','DROUGHT'],['Public Evidence Project / Compute Atlas','Source-linked infrastructure records. Public Evidence Project / Compute Atlas by Edward Kubiak, CC BY 4.0. Locations and operating status vary in certainty.','https://publicevidence.org/data/national-data-center-public-records','DATA CENTERS'],['Google Environmental Report','Operator-reported 2025 withdrawal, discharge and consumption at reporting localities.','https://sustainability.google/reports/','REPORTED WATER USE'],['FAO and NC State Extension','Crop-water reference coefficients and regional crop-rotation guidance.','https://content.ces.ncsu.edu/north-carolina-soybean-production-guide/rotational-considerations','CROP REFERENCES']];el('#main').innerHTML=shell('Sources','The datasets and agricultural references behind MESORA.',`<div class="source-cards">${rows.map(([name,desc,url,tag])=>`<article class="source-card"><span class="eyebrow">${tag}</span><h2>${name}</h2><p>${desc}</p>${link(url,'Visit source')}</article>`).join('')}</div><p class="source-bottom">Observed and reported inputs retain their dates and units. Planning estimates and user-defined scenarios are labeled in the results. ${link('https://creativecommons.org/licenses/by/4.0/','Record attribution license')} · ${link('https://www.openstreetmap.org/copyright','OpenStreetMap contributors')}</p>`);}

 function render(route){if(map){map.remove();map=null;marker=null;overlay=null;boundaryLayer=null;}state.route=route;el('#site-menu').hidden=true;el('#menu-toggle').setAttribute('aria-expanded','false');document.body.classList.add('workspace-open');({explore,water,climate,planner,compare,infrastructure,sources:methods}[route]||explore)();bindRecovery();if(!state.weather&&!state.loading&&!state.attempted)loadEvidence();window.scrollTo(0,0);}
 return {render,state,validateBoundary,outerBoundary,countyAt,csv,parseResults};
})();
